import { Card } from "@/components/ui/card";
import {
  Form,
  FormField,
  FormItem,
  FormLabel,
  FormControl,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import * as z from "zod";
import { useForm } from "react-hook-form";
import React from "react";
import { zodResolver } from "@hookform/resolvers/zod";

const schema = z.object({
  fullName: z.string().min(1),
  email: z.string(),
});

type FormData = z.infer<typeof schema>;

function page() {
  const form = useForm<FormData>({ resolver: zodResolver(schema) });

  return (
    <Card
      className="min-w-[326px] w-[50vw] min-h-[326px] h-[75vh]
                  bg-white rounded-[20px] overflow-auto"
      style={{ boxShadow: "4px 4px 10px rgba(0, 0, 0, 0.25)" }}
    >
      <Form {...form}>
        <form className="flex flex-col items-start gap-1.5 w-full sm:w-[360px] max-w-full p-4 relative">
          {/* Nome Completo */}
          <FormField
            control={form.control}
            name="fullName"
            render={({ field }) => (
              <FormItem className="w-full">
                <FormLabel className="text-sm font-medium text-foreground">
                  Nome Completo
                </FormLabel>
                <FormControl>
                  <Input
                    {...field}
                    placeholder="Ex. Julia Firmino"
                    className="w-full bg-white border border-border rounded-md h-12 px-1"
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          {/* E-mail */}
          <FormField
            control={form.control}
            name="email"
            render={({ field }) => (
              <FormItem className="w-full mt-1">
                <FormLabel className="text-sm font-medium text-foreground">
                  Email
                </FormLabel>
                <FormControl>
                  <Input
                    {...field}
                    type="email"
                    placeholder="julia@example.com"
                    className="w-full bg-white border border-border rounded-md h-12 px-1 text-sm text-foreground/50"
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
        </form>
      </Form>
    </Card>
  );
}

export default page;
